import re
from collections import deque
from decimal import Decimal


class ExpressionCalculator:
    OPERATOR_PRIORITY = [0, 3, 2, 1, -1, 1, 0, 2]
    OPERATORS = {'+', '-', '*', '/', '(', ')', '%'}
    NEGATIVE_PRECEDING_CHARS = {'+', '-', '*', '/', '(', 'E', 'e'}

    def __init__(self):
        self.postfix_stack = deque()
        self.operat_priority = self.OPERATOR_PRIORITY

    def calculate(self, expression):
        self.prepare(self.transform(expression))
        return self._evaluate_postfix()

    def prepare(self, expression):
        op_stack = deque([','])
        arr = list(expression)
        current_index = 0
        count = 0

        for i, current_op in enumerate(arr):
            if self.is_operator(current_op):
                if count > 0:
                    self.postfix_stack.append("".join(arr[current_index: current_index + count]))
                peek_op = op_stack[-1]
                if current_op == ')':
                    while op_stack[-1] != '(':
                        self.postfix_stack.append(str(op_stack.pop()))
                    op_stack.pop()
                else:
                    while current_op != '(' and peek_op != ',' and self.compare(current_op, peek_op):
                        self.postfix_stack.append(str(op_stack.pop()))
                        peek_op = op_stack[-1]
                    op_stack.append(current_op)

                count = 0
                current_index = i + 1
            else:
                count += 1

        if count > 1 or (count == 1 and not self.is_operator(arr[current_index])):
            self.postfix_stack.append("".join(arr[current_index: current_index + count]))

        while op_stack[-1] != ',':
            self.postfix_stack.append(str(op_stack.pop()))

    def _evaluate_postfix(self):
        result_stack = deque()
        self.postfix_stack.reverse()

        while self.postfix_stack:
            current_op = self.postfix_stack.pop()
            if not self.is_operator(current_op):
                result_stack.append(self._normalize_negative(current_op))
            else:
                second_value = result_stack.pop()
                first_value = result_stack.pop()

                first_value = self._normalize_negative(first_value)
                second_value = self._normalize_negative(second_value)

                temp_result = self._calculate(first_value, second_value, current_op)
                result_stack.append(str(temp_result))

        return float(eval("*".join(result_stack)))

    @staticmethod
    def _normalize_negative(value):
        return value.replace("~", "-")

    @staticmethod
    def is_operator(c):
        return c in ExpressionCalculator.OPERATORS

    def compare(self, cur, peek):
        cur_normalized = self._normalize_operator(cur)
        peek_normalized = self._normalize_operator(peek)
        return self.operat_priority[ord(peek_normalized) - 40] >= self.operat_priority[ord(cur_normalized) - 40]

    @staticmethod
    def _normalize_operator(op):
        return '/' if op == '%' else op

    @staticmethod
    def _calculate(first_value, second_value, current_op):
        if current_op == '+':
            return Decimal(first_value) + Decimal(second_value)
        elif current_op == '-':
            return Decimal(first_value) - Decimal(second_value)
        elif current_op == '*':
            return Decimal(first_value) * Decimal(second_value)
        elif current_op == '/':
            return Decimal(first_value) / Decimal(second_value)
        elif current_op == '%':
            return Decimal(first_value) % Decimal(second_value)
        else:
            raise ValueError("Unexpected operator: {}".format(current_op))

    @staticmethod
    def transform(expression):
        expression = ExpressionCalculator._remove_whitespace(expression)
        expression = ExpressionCalculator._remove_assignment(expression)
        arr = list(expression)

        for i, c in enumerate(arr):
            if c == '-':
                if i == 0:
                    arr[i] = '~'
                else:
                    prev_c = arr[i - 1]
                    if prev_c in ExpressionCalculator.NEGATIVE_PRECEDING_CHARS:
                        arr[i] = '~'

        if arr[0] == '~' and (len(arr) > 1 and arr[1] == '('):
            arr[0] = '-'
            return "0" + "".join(arr)
        else:
            return "".join(arr)

    @staticmethod
    def _remove_whitespace(expression):
        return re.sub(r"\s+", "", expression)

    @staticmethod
    def _remove_assignment(expression):
        return re.sub(r"=$", "", expression)
